import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"砂金效应","description":"","frontmatter":{"title":"砂金效应","phenomenon":"aventurescence"},"headers":[],"relativePath":"zh/classification/optical-phenomena/aventurescence.md","filePath":"zh/classification/optical-phenomena/aventurescence.md","lastUpdated":1790876393000}'),l={name:"zh/classification/optical-phenomena/aventurescence.md"};function o(s,e,i,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="砂金效应" tabindex="-1">砂金效应 <a class="header-anchor" href="#砂金效应" aria-label="Permalink to &quot;砂金效应&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>砂金效应是当宝石内部含有大量小而平的金属矿物薄片（最常见为赤 铁矿 / 铜片）时，光从这些薄片反射形成闪烁的金属光泽。最著名的 是：</p><ul><li><strong>日光石 (Sunstone)</strong> —— 长石族中含赤铁矿 / 针铁矿薄片</li><li><strong>砂金石 (Aventurine)</strong> —— 石英中含铬云母 / 赤铁矿薄片（绿色、棕色变种）</li><li><strong>东陵玉</strong> —— 与砂金石同类，绿色最常见 薄片越大、越反光，效果越明显。</li></ul><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>薄片反射：宝石结晶过程中赤铁矿（Fe₂O₃）或针铁矿（FeO(OH)） 沿特定方向析出为细小六边形或圆形薄片，每片尺寸约 0.1–1 mm。 当光从不同方向入射，各薄片依次闪烁形成&quot;星光&quot;般的金属闪烁 效果。绿色砂金石中的铬云母反射绿色光，红/棕色来自赤铁矿。</p><h2 id="示例宝石" tabindex="-1">示例宝石 <a class="header-anchor" href="#示例宝石" aria-label="Permalink to &quot;示例宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>包裹体薄片</th><th>宿主矿物</th></tr></thead><tbody><tr><td>Sunstone (Oregon) / 日光石</td><td>copper / hematite</td><td>Feldspar (oligoclase / labradorite)</td></tr><tr><td>Aventurine Quartz (green) / 砂金石</td><td>chrome-mica / fuchsite</td><td>Quartz</td></tr><tr><td>Aventurine Quartz (red-brown) / 砂金石</td><td>hematite</td><td>Quartz</td></tr><tr><td>Imperial Sunstone / 帝王日光石</td><td>large copper platelets</td><td>Feldspar</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA：现象宝石指南</a><span>光学现象的观察方式与宝石学语境</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA：现象弧面宝石的光学效应</a><span>弧面切割、光源、角度与光学表现</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">光学现象总览</a>。</em></p>',10)])])}const u=t(l,[["render",o]]);export{m as __pageData,u as default};
